-- Fakt kartochkalari orqa tomonining ruscha matni — 78-partiya:
-- Toshmuhammad Sarimsoqov, Turdi Farog'iy, Ubay Orifov.

UPDATE fact_cards SET detail_ru = 'Ташмухаммад Сарымсаков родился 9 октября 1915 года в селении Шахрихан Андижанской области. Позже он стал одним из самых известных учёных-математиков Узбекистана. Источник: Ziyouz.com, раздел «Узбекские просвещённые деятели».' WHERE id = 2362;
UPDATE fact_cards SET detail_ru = 'Сарымсаков окончил Среднеазиатский университет в 1936 году и прошёл в этом же заведении путь от ассистента до ректора. В 1942 году он получил учёную степень доктора физико-математических наук и звание профессора. Источник: Ziyouz.com, раздел «Узбекские просвещённые деятели».' WHERE id = 2363;
UPDATE fact_cards SET detail_ru = 'Исследования Сарымсакова посвящены теории вероятностей, геофизике и метеорологии. Он был основателем ташкентской научной школы по топологии и функциональному анализу и разработал теорию полуполей и её приложение к теории вероятностей. Источник: Ziyouz.com, раздел «Узбекские просвещённые деятели».' WHERE id = 2364;
UPDATE fact_cards SET detail_ru = 'В 1943 году Сарымсаков стал академиком Академии наук Узбекистана и работал в академии вице-президентом, а затем президентом. Источники указывают год начала президентства по-разному: в статье о Сарымсакове — 1946 год, а в статье о первом президенте академии Ташмухаммаде Кары-Ниязи сказано, что тот занимал эту должность до 1947 года. Источник: Ziyouz.com, раздел «Узбекские просвещённые деятели».' WHERE id = 2365;
UPDATE fact_cards SET detail_ru = 'В 1959–1971 годах Сарымсаков был министром высшего и среднего специального образования Узбекистана. До этого он работал и в должности ректора университета. Источник: Ziyouz.com, раздел «Узбекские просвещённые деятели».' WHERE id = 2366;
UPDATE fact_cards SET detail_ru = 'Сарымсаков был дважды удостоен Государственной премии Узбекистана имени Беруни — в 1967 и 1992 годах. В 1990 году он был награждён званием Героя Труда. Источник: Ziyouz.com, раздел «Узбекские просвещённые деятели».' WHERE id = 2367;
UPDATE fact_cards SET detail_ru = 'Ташмухаммад Сарымсаков умер 17 декабря 1995 года в Ташкенте. На исходе жизни, с 1988 года, он работал советником в Президиуме Академии наук Узбекистана. Источник: Ziyouz.com, раздел «Узбекские просвещённые деятели».' WHERE id = 2368;

UPDATE fact_cards SET detail_ru = 'Турди родился в XVII веке в Бухаре; точный год его рождения неизвестен. В персидско-таджикских стихах он употреблял псевдоним Фараги. Источник: Ziyouz.com, раздел «Узбекская классическая словесность».' WHERE id = 1983;
UPDATE fact_cards SET detail_ru = 'Турди учился в бухарских медресе. Он писал зрелые стихи на обоих языках — на узбекском и на персидском. Источник: Ziyouz.com.' WHERE id = 1984;
UPDATE fact_cards SET detail_ru = 'Турди был одним из видных политических деятелей рода юз и при Абдулазиз-хане служил придворным сановником. Когда к власти пришёл Субханкули-хан, он был отстранён от двора. Источник: Ziyouz.com.' WHERE id = 1985;
UPDATE fact_cards SET detail_ru = 'В 1685–1686 годах Турди деятельно участвовал в народном восстании против Аштарханидов. После подавления восстания он ушёл в Джизак, а затем в Худжанд. Источник: Ziyouz.com.' WHERE id = 1986;
UPDATE fact_cards SET detail_ru = 'От Турди до нас дошло восемнадцать стихотворений: двенадцать газелей, пять мухаммасов и один фард, всего 434 строки. Его газели отличаются от газелей других поэтов необычайной сжатостью — они состоят из трёх-пяти бейтов. Источник: Ziyouz.com.' WHERE id = 1987;
UPDATE fact_cards SET detail_ru = 'В 1691 году Турди создал сатиру о Субханкули-хане в 165 строк. Этим сочинением он поднял узбекскую сатиру после Алишера Навои на новую ступень. Источник: Ziyouz.com.' WHERE id = 1988;
UPDATE fact_cards SET detail_ru = 'В газели, начинающейся словами «Узкие сердцем беки, не говорите „я“ — будьте шире», Турди призывает беков к широте, к согласию между собою и к равенству. Есть в ней строка: «Это земля узбеков девяноста двух родов — будьте равны». Источник: Ziyouz.com.' WHERE id = 1989;
UPDATE fact_cards SET detail_ru = 'Турди умер в 1699/1700 году в городе Худжанде. Его стихи позже нашёл А. Маджиди, и они были изданы в 1924–1925 годах. Источник: Ziyouz.com.' WHERE id = 1990;

UPDATE fact_cards SET detail_ru = 'По «Национальной энциклопедии Узбекистана», Убай Арифович Арифов родился 15 июня 1905 года в Коканде. Он известен как учёный-физик, государственный и общественный деятель. Источник: библиотека Ziyouz.com, «Национальная энциклопедия Узбекистана», буква О, статья «Арифов Убай Арифович».' WHERE id = 2369;
UPDATE fact_cards SET detail_ru = 'В 1931 году он окончил Педагогическую академию Узбекистана и работал в Кокандском хлопковом институте (1932–1934) и в УзГУ (1935–1941). В 1954 году он стал доктором физико-математических наук, в 1956-м — профессором. Источник: библиотека Ziyouz.com, «Национальная энциклопедия Узбекистана», буква О, статья «Арифов Убай Арифович».' WHERE id = 2370;
UPDATE fact_cards SET detail_ru = 'Он был директором Института ядерной физики АН Узбекистана (1956–1962, 1967–1969) и директором Института электроники (1966–1976), работал и в Физико-техническом институте (1945–1956, 1963–1967). Источник: библиотека Ziyouz.com, «Национальная энциклопедия Узбекистана», буква О, статья «Арифов Убай Арифович».' WHERE id = 2371;
UPDATE fact_cards SET detail_ru = 'С 1956 года Убай Арифов был академиком АН Узбекистана, а в 1962–1966 годах — президентом АН Узбекистана. Работал он и как государственный и общественный деятель. Источник: библиотека Ziyouz.com, «Национальная энциклопедия Узбекистана», буква О, статья «Арифов Убай Арифович».' WHERE id = 2372;
UPDATE fact_cards SET detail_ru = 'Его основные научные работы посвящены физической электронике, ядерной и радиационной физике, гелиоэнергетике, а также вопросам первичной обработки хлопкового сырья. Источник: библиотека Ziyouz.com, «Национальная энциклопедия Узбекистана», буква О, статья «Арифов Убай Арифович».' WHERE id = 2373;
UPDATE fact_cards SET detail_ru = 'Он установил неизвестные прежде науке явления — сложные процессы, происходящие в твёрдом теле под действием атомных частиц, обнаружение и разделение разных групп вторичных ионов и электронов, способы изменения свойств поверхности твёрдых тел. На этой основе были созданы способы обработки материалов для электронной техники, микроэлектроники и машиностроения. Источник: библиотека Ziyouz.com, «Национальная энциклопедия Узбекистана», буква О, статья «Арифов Убай Арифович».' WHERE id = 2374;
UPDATE fact_cards SET detail_ru = 'В итоге исследований под его руководством были решены задачи полного оголения, сортировки и очистки семенного и технического хлопкового семени, а также выполнены работы по обращению солнечной энергии в электрическую и по созданию гелиотехнических устройств. По его почину с 1965 года в Ташкенте начал издаваться международный журнал «Гелиотехника». Источник: библиотека Ziyouz.com, «Национальная энциклопедия Узбекистана», буква О, статья «Арифов Убай Арифович».' WHERE id = 2375;
UPDATE fact_cards SET detail_ru = 'Его книги о взаимодействии атомных частиц с металлом и поверхностью твёрдого тела были изданы в 1961 году в Ташкенте и в 1968 году в Москве. В 1959 году он получил звание заслуженного деятеля науки и техники Узбекистана, а в 1968-м стал лауреатом Государственной премии Узбекистана имени Беруни. Источник: библиотека Ziyouz.com, «Национальная энциклопедия Узбекистана», буква О, статья «Арифов Убай Арифович».' WHERE id = 2376;
UPDATE fact_cards SET detail_ru = 'Убай Арифов умер 24 декабря 1976 года в Ташкенте. Его имя присвоено Институту электроники АН Узбекистана и одной из улиц Юнусабадского района Ташкента. Источник: библиотека Ziyouz.com, «Национальная энциклопедия Узбекистана», буква О, статья «Арифов Убай Арифович».' WHERE id = 2377;
